/**
 * Unit tests for JacksonAnnotationIntrospector.findObjectReferenceInfo
 */
public class JacksonAnnotationIntrospector_findObjectReferenceInfo_TriageGen1Test {

    private JacksonAnnotationIntrospector introspector;

    @Before
    public void setUp() {
        introspector = new JacksonAnnotationIntrospector();
    }



    /**
     * Test case where the annotation JsonIdentityReference IS present.
     * This tests the branch where ref != null and verifies withAlwaysAsId is called.
     */
    @Test
    public void testFindObjectReferenceInfo_WithAnnotation() {
        // Arrange
        Annotated mockAnn = mock(Annotated.class);
        ObjectIdInfo mockObjectIdInfo = mock(ObjectIdInfo.class);

        // Create a real annotation instance or a mock that mimics JsonIdentityReference
        // Because _findAnnotation is used internally, we need the mockAnn to return it.
        // In Jackson, _findAnnotation looks at the annotations on the Annotated object.
        JsonIdentityReference mockRef = mock(JsonIdentityReference.class);
        when(mockRef.alwaysAsId()).thenReturn(true);

        // Mocking the behavior of Annotated to return our mock annotation
        // Note: Jackson's _findAnnotation implementation calls ann.getAnnotation(type)
        when(mockAnn.getAnnotation(JsonIdentityReference.class)).thenReturn(mockRef);

        // Mock the immutable 'withAlwaysAsId' return value
        ObjectIdInfo expectedNewObjectIdInfo = mock(ObjectIdInfo.class);
        when(mockObjectIdInfo.withAlwaysAsId(true)).thenReturn(expectedNewNewObjectIdInfo(expectedNewObjectIdInfo, true));
        // Actually, since withAlwaysAsId returns a new instance, let's simplify:
        when(mockObjectIdInfo.withAlwaysAsId(true)).thenReturn(expectedNewObjectIdInfo);

        // Act
        ObjectIdInfo result = introspector.findObjectReferenceInfo(mockAnn, mockObjectIdInfo);

        // Assert
        assertNotNull(result);
        assertNotSame(mockObjectIdInfo, result);
        assertEquals(expectedNewObjectIdInfo, result);
        verify(mockObjectIdInfo).withAlwaysAsId(true);
    }



    // Helper to satisfy the logic if needed, though the mock approach above is cleaner
    private ObjectIdInfo expectedNewNewObjectIdInfo(ObjectIdInfo info, boolean val) {
        return info; 
    }
}

